unsafe {
    let mut current_block: u64;
    let input = (*ctxt).input;
    let mut cur: *const c_uchar;
    let mut avail: size_t;
    let c: c_int;
    if ctxt.is_null()
        || (*ctxt).instate as c_int == XML_PARSER_EOF as c_int
        || input.is_null()
    {
        return;
    }
    avail = (*input).end.offset_from((*input).cur) as c_long as size_t;
    if avail < INPUT_CHUNK as size_t {
        xmlParserGrow(ctxt);
        if (*ctxt).instate as c_int == XML_PARSER_EOF as c_int
            || (*input).cur >= (*input).end
        {
            return;
        }
        avail = (*input).end.offset_from((*input).cur) as c_long as size_t;
    }
    cur = (*input).cur as *const c_uchar;
    c = *cur as c_int;
    if c < 0x80 as c_int {
        if c == '\n' as i32 {
            (*input).cur = (*input).cur.offset(1);
            (*input).line += 1;
            (*input).col = 1 as c_int;
        } else if c == '\r' as i32 {
            let step = if *cur.offset(1) as c_int == '\n' as i32 {
                2
            } else {
                1
            };
            (*input).cur = (*input).cur.offset(step as isize);
            (*input).line += 1;
            (*input).col = 1 as c_int;
            return;
        } else {
            (*input).cur = (*input).cur.offset(1);
            (*input).col += 1;
        }
    } else {
        (*input).col += 1;
        let b1 = if avail >= 2 as size_t {
            *cur.offset(1) as c_int
        } else {
            0
        };
        if avail < 2 as size_t || b1 & 0xc0 as c_int != 0x80 as c_int {
            current_block = 10664207195514096503;
        } else if c < 0xe0 as c_int {
            if c < 0xc2 as c_int {
                current_block = 10664207195514096503;
            } else {
                (*input).cur = (*input).cur.offset(2);
                current_block = 14434620278749266018;
            }
        } else {
            let val: c_uint = (c << 8 as c_int | b1) as c_uint;
            let b2 = if avail >= 3 as size_t {
                *cur.offset(2) as c_int
            } else {
                0
            };
            if avail < 3 as size_t || b2 & 0xc0 as c_int != 0x80 as c_int {
                current_block = 10664207195514096503;
            } else if c < 0xf0 as c_int {
                if val < 0xe0a0 as c_uint
                    || val >= 0xeda0 as c_uint && val < 0xee00 as c_uint
                {
                    current_block = 10664207195514096503;
                } else {
                    (*input).cur = (*input).cur.offset(3);
                    current_block = 14434620278749266018;
                }
            } else {
                let b3 = if avail >= 4 as size_t {
                    *cur.offset(3) as c_int
                } else {
                    0
                };
                if avail < 4 as size_t || b3 & 0xc0 as c_int != 0x80 as c_int {
                    current_block = 10664207195514096503;
                } else if val < 0xf090 as c_uint || val >= 0xf490 as c_uint {
                    current_block = 10664207195514096503;
                } else {
                    (*input).cur = (*input).cur.offset(4);
                    current_block = 14434620278749266018;
                }
            }
        }
        match current_block {
            14434620278749266018 => {}
            _ => {
                if (*input).flags as c_uint & XML_INPUT_ENCODING_ERROR == 0 as c_uint {
                    let err_cur = (*input).cur;
                    let err_end = (*input).end;
                    if ctxt.is_null()
                        || input.is_null()
                        || (err_end.offset_from(err_cur) as c_long) < 4 as c_long
                    {
                        __xmlErrEncoding(
                            ctxt,
                            XML_ERR_INVALID_CHAR,
                            b"Input is not proper UTF-8, indicate encoding !\n\0" as *const u8
                                as *const c_char,
                            ::core::ptr::null::<xmlChar>(),
                            ::core::ptr::null::<xmlChar>(),
                        );
                    } else {
                        let mut buffer: [c_char; 150] = [0; 150];
                        let e0 = *err_cur.offset(0) as c_int;
                        let e1 = *err_cur.offset(1) as c_int;
                        let e2 = *err_cur.offset(2) as c_int;
                        let e3 = *err_cur.offset(3) as c_int;
                        snprintf(
                            &raw mut buffer as *mut c_char,
                            149 as size_t,
                            b"Bytes: 0x%02X 0x%02X 0x%02X 0x%02X\n\0" as *const u8
                                as *const c_char,
                            e0,
                            e1,
                            e2,
                            e3,
                        );
                        __xmlErrEncoding(
                            ctxt,
                            XML_ERR_INVALID_CHAR,
                            b"Input is not proper UTF-8, indicate encoding !\n%s\0" as *const u8
                                as *const c_char,
                            &raw mut buffer as *mut c_char as *mut xmlChar,
                            ::core::ptr::null::<xmlChar>(),
                        );
                    }
                    (*input).flags =
                        ((*input).flags as c_uint | XML_INPUT_ENCODING_ERROR) as c_int;
                }
                (*input).cur = (*input).cur.offset(1);
                return;
            }
        }
    };
}

